

# This file was *autogenerated* from the file /Users/masaori/git/masaori/math/.claude/worktrees/reflective-fluttering-panda/exact-solution-of-2d-ising-model/sagemath/check/190_claim_exp_sum/check_01_exp_sum_vs_delta.sage
from sage.all_cmdline import *   # import sage library

_sage_const_2 = Integer(2); _sage_const_3 = Integer(3); _sage_const_4 = Integer(4); _sage_const_5 = Integer(5); _sage_const_6 = Integer(6); _sage_const_7 = Integer(7); _sage_const_8 = Integer(8); _sage_const_0p0 = RealNumber('0.0'); _sage_const_0p0j = ComplexNumber(0, '0.0'); _sage_const_1 = Integer(1); _sage_const_1j = ComplexNumber(0, '1'); _sage_const_0 = Integer(0); _sage_const_1en9 = RealNumber('1e-9')# exp_sum: sum_{j=1}^{M} exp(2 pi i j k / M) = M delta^M_{(k,0)}
#
# 独立経路:
#   経路 A（素朴）: j=1..M の複素指数を 1 つずつ足し上げる（定義そのもの）
#   経路 B（閉じた表示）: M * delta^M_{(k,0)}
# 両者を M = 2..8、k = -3M..3M（0 を含む）で突き合わせる。
import os
_dir = os.path.dirname(os.path.abspath(__file__)) if '__file__' in dir() else '.'
load(os.path.join(_dir, '../../_shared/operators.sage'))

rep = CheckReport("exp_sum: 素朴な有限和 vs M*delta^M_{(k,0)}")

M_LIST = [_sage_const_2 , _sage_const_3 , _sage_const_4 , _sage_const_5 , _sage_const_6 , _sage_const_7 , _sage_const_8 ]


def exp_sum_naive(k, M):
    """定義どおり j=1..M を 1 項ずつ足す。"""
    tot = _sage_const_0p0  + _sage_const_0p0j 
    for j in range(_sage_const_1 , int(M) + _sage_const_1 ):
        tot += _np.exp(_sage_const_1j  * _sage_const_2  * _np.pi * float(j) * float(k) / float(M))
    return tot


n_zero = _sage_const_0 
n_nonzero = _sage_const_0 
for M in M_LIST:
    for k in range(-_sage_const_3  * int(M), _sage_const_3  * int(M) + _sage_const_1 ):
        lhs = exp_sum_naive(k, M)
        rhs = float(M) * delta_M(k, _sage_const_0 , M)
        rep.close(lhs, rhs, "M=%d k=%d" % (M, k))
        if (k % int(M)) == _sage_const_0 :
            n_zero += _sage_const_1 
        else:
            n_nonzero += _sage_const_1 

print("  k が M の倍数の場合: %d 件、そうでない場合: %d 件" % (n_zero, n_nonzero))

# 反例探し: k が M の倍数でないのに和が 0 にならないケースが無いか、
# 絶対値の最大を明示的に見る（相対誤差だけだと見落としうるため）。
worst = _sage_const_0p0 
worst_at = None
for M in M_LIST:
    for k in range(-_sage_const_3  * int(M), _sage_const_3  * int(M) + _sage_const_1 ):
        if (k % int(M)) == _sage_const_0 :
            continue
        v = abs(exp_sum_naive(k, M))
        if v > worst:
            worst = v
            worst_at = (M, k)
print("  k 非倍数のときの |和| の最大: %.3e at (M,k)=%s" % (worst, worst_at))
rep.truth(worst < _sage_const_1en9 , "k が M の倍数でないとき和は 0（|和|最大 %.3e）" % worst)

rep.finish()

